var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("Packaging");
if (!scene.IsValid()) {
    scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/SubGames/Packaging.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
}
var roots = scene.GetRootGameObjects();
Sim.SubGames.Packaging.PackagingFeedback fb = null;
UnityEngine.Transform content = null;
foreach (var r in roots) {
    if (fb == null) fb = r.GetComponentInChildren<Sim.SubGames.Packaging.PackagingFeedback>(true);
    foreach (var t in r.GetComponentsInChildren<UnityEngine.Transform>(true)) {
        if (t.name == "Content" && t.GetComponentInParent<UnityEngine.Canvas>() != null) { content = t; break; }
    }
    if (content != null) break;
}
if (fb == null || content == null) { Debug.LogError("missing refs"); return; }

// Already exists?
var existing = content.Find("Result Panel");
if (existing != null) UnityEngine.Object.DestroyImmediate(existing.gameObject, true);

// Build Result Panel
var panelGO = new UnityEngine.GameObject("Result Panel", typeof(UnityEngine.RectTransform), typeof(UnityEngine.UI.Image));
panelGO.transform.SetParent(content, false);
var panelRT = (UnityEngine.RectTransform)panelGO.transform;
panelRT.anchorMin = new UnityEngine.Vector2(0, 0);
panelRT.anchorMax = new UnityEngine.Vector2(1, 1);
panelRT.offsetMin = UnityEngine.Vector2.zero;
panelRT.offsetMax = UnityEngine.Vector2.zero;
var panelImg = panelGO.GetComponent<UnityEngine.UI.Image>();
panelImg.color = new UnityEngine.Color(0f, 0f, 0f, 0.6f); // dim overlay

// Card child
var cardGO = new UnityEngine.GameObject("Card", typeof(UnityEngine.RectTransform), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.VerticalLayoutGroup), typeof(UnityEngine.UI.ContentSizeFitter));
cardGO.transform.SetParent(panelGO.transform, false);
var cardRT = (UnityEngine.RectTransform)cardGO.transform;
cardRT.anchorMin = new UnityEngine.Vector2(0.5f, 0.5f);
cardRT.anchorMax = new UnityEngine.Vector2(0.5f, 0.5f);
cardRT.pivot     = new UnityEngine.Vector2(0.5f, 0.5f);
cardRT.sizeDelta = new UnityEngine.Vector2(480f, 0f);
cardRT.anchoredPosition = UnityEngine.Vector2.zero;
var cardImg = cardGO.GetComponent<UnityEngine.UI.Image>();
cardImg.color = new UnityEngine.Color(0.97f, 0.95f, 0.90f, 1f);
var vlg = cardGO.GetComponent<UnityEngine.UI.VerticalLayoutGroup>();
vlg.padding = new UnityEngine.RectOffset(24, 24, 24, 24);
vlg.spacing = 10f;
vlg.childControlWidth = true;
vlg.childControlHeight = false;
vlg.childForceExpandWidth = true;
vlg.childForceExpandHeight = false;
var csf = cardGO.GetComponent<UnityEngine.UI.ContentSizeFitter>();
csf.verticalFit = UnityEngine.UI.ContentSizeFitter.FitMode.PreferredSize;

// Helper: make a TMP child
TMPro.TextMeshProUGUI MakeText(string name, string defaultText, int fontSize, TMPro.FontStyles style) {
    var go = new UnityEngine.GameObject(name, typeof(UnityEngine.RectTransform));
    go.transform.SetParent(cardGO.transform, false);
    var t = go.AddComponent<TMPro.TextMeshProUGUI>();
    t.text = defaultText;
    t.fontSize = fontSize;
    t.fontStyle = style;
    t.alignment = TMPro.TextAlignmentOptions.Center;
    t.color = new UnityEngine.Color(0.15f, 0.15f, 0.15f, 1f);
    var le = go.AddComponent<UnityEngine.UI.LayoutElement>();
    le.preferredHeight = fontSize + 8;
    return t;
}

var rating    = MakeText("Rating",    "Emballage prêt",         28, TMPro.FontStyles.Bold);
var score     = MakeText("Score",     "0 / 1000",                22, TMPro.FontStyles.Normal);
var space     = MakeText("Space",     "Espace : 0%",             16, TMPro.FontStyles.Normal);
space.alignment = TMPro.TextAlignmentOptions.Left;
var fragile   = MakeText("Fragile",   "Fragiles protégés : --",  16, TMPro.FontStyles.Normal);
fragile.alignment = TMPro.TextAlignmentOptions.Left;
var heavy     = MakeText("Heavy",     "Lourds bien posés : --",  16, TMPro.FontStyles.Normal);
heavy.alignment = TMPro.TextAlignmentOptions.Left;
var items     = MakeText("Items",     "Items placés : 0 / 0",    16, TMPro.FontStyles.Normal);
items.alignment = TMPro.TextAlignmentOptions.Left;

// Close button
var closeGO = new UnityEngine.GameObject("Close", typeof(UnityEngine.RectTransform), typeof(UnityEngine.UI.Image), typeof(UnityEngine.UI.Button), typeof(UnityEngine.UI.LayoutElement));
closeGO.transform.SetParent(cardGO.transform, false);
var closeImg = closeGO.GetComponent<UnityEngine.UI.Image>();
closeImg.color = new UnityEngine.Color(0.20f, 0.50f, 0.30f, 1f);
var closeBtn = closeGO.GetComponent<UnityEngine.UI.Button>();
var closeLE = closeGO.GetComponent<UnityEngine.UI.LayoutElement>();
closeLE.preferredHeight = 44f;
var closeLblGO = new UnityEngine.GameObject("Label", typeof(UnityEngine.RectTransform));
closeLblGO.transform.SetParent(closeGO.transform, false);
var closeLblRT = (UnityEngine.RectTransform)closeLblGO.transform;
closeLblRT.anchorMin = UnityEngine.Vector2.zero;
closeLblRT.anchorMax = UnityEngine.Vector2.one;
closeLblRT.offsetMin = UnityEngine.Vector2.zero;
closeLblRT.offsetMax = UnityEngine.Vector2.zero;
var closeLbl = closeLblGO.AddComponent<TMPro.TextMeshProUGUI>();
closeLbl.text = "Fermer";
closeLbl.alignment = TMPro.TextAlignmentOptions.Center;
closeLbl.fontSize = 18;
closeLbl.color = UnityEngine.Color.white;
closeLbl.fontStyle = TMPro.FontStyles.Bold;

// Wire all PackagingFeedback fields via SerializedObject
var so = new UnityEditor.SerializedObject(fb);
so.Update();
so.FindProperty("resultPanel").objectReferenceValue          = panelGO;
so.FindProperty("ratingLabel").objectReferenceValue          = rating;
so.FindProperty("scoreLabel").objectReferenceValue           = score;
so.FindProperty("spaceBreakdownLabel").objectReferenceValue  = space;
so.FindProperty("fragileBreakdownLabel").objectReferenceValue= fragile;
so.FindProperty("heavyBreakdownLabel").objectReferenceValue  = heavy;
so.FindProperty("itemsBreakdownLabel").objectReferenceValue  = items;
so.FindProperty("closeButton").objectReferenceValue          = closeBtn;
so.ApplyModifiedProperties();

// Hide by default — manager calls ShowValidationResult on validate
panelGO.SetActive(false);

UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("[PkgModal] Built — panel=" + panelGO.GetInstanceID() + " close=" + closeGO.GetInstanceID() + " — saved.");
